<script setup>
import { ref, onMounted } from 'vue';
import HeaderComponent from "../HeaderComponent.vue";

const lines = [
  '안녕하세요,',
  '수 많은 공간의 첫인상을 디자인 했던',
  '경험을 바탕으로, 이제는 웹에서',
  '더 깊은 인상을 남기는',
  '웹퍼블리셔 한예린 입니다:D'
];

const displayedLines = ref(lines.map(() => '')); // 각 줄에 대해 타이핑된 텍스트
const currentLineIndex = ref(0); // 현재 타이핑 중인 줄

// onMounted에서 타이핑 애니메이션 시작
onMounted(() => {
  lines.forEach((text, index) => {
    setTimeout(() => {
      let i = 0;
      const interval = setInterval(() => {
        displayedLines.value[index] += text[i];
        i++;
        if (i === text.length) {
          clearInterval(interval);
          if (index + 1 < lines.length) {
            // 모든 타이핑이 끝난 후, 다음 줄로 넘어가기
            currentLineIndex.value = index + 1;
          }
        }
      }, 100); // 글자당 타이핑 속도 조정
    }, index * 1800); // 각 줄 간 딜레이 설정
  });
});
</script>